// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"AP Spanish is organized around six cultural themes. Let's start with families and communities across the Spanish-speaking world.","blocks":[{"t":"key","text":"In many Spanish-speaking cultures, extended families play a central role, with grandparents, aunts, uncles and godparents (padrinos) closely involved. Traditions like the quinceañera mark coming of age."},{"t":"p","text":"Community and citizenship: volunteering (el voluntariado), community organizations and civic participation. Compare cultural practices with your own community."},{"t":"p","text":"Useful vocabulary for presentations: la convivencia (living together), el compromiso (commitment), la ciudadanía (citizenship), las costumbres (customs)."},{"t":"p","text":"For cultural comparisons on the exam, describe a practice in a Spanish-speaking community, compare it to your own, and explain the difference or similarity with specific examples."}]},{"say":"The subjunctive expresses wishes, doubts, emotions and recommendations. It's essential at the AP level.","blocks":[{"t":"key","text":"Form the present subjunctive from the yo present form: drop the -o and add opposite endings. -ar verbs take -e endings (hable); -er/-ir verbs take -a endings (coma, viva). Irregulars: sea, vaya, esté, dé, sepa, haya."},{"t":"p","text":"Use the subjunctive after WEIRDO triggers with a change of subject and que: Wishes, Emotions, Impersonal expressions, Recommendations, Doubt/Denial, Ojalá."},{"t":"list","items":["Quiero que estudies. (I want you to study.)","Es importante que la comunidad participe.","Dudo que llueva."]},{"t":"ex","problem":"\"My parents hope that I go to college.\"","steps":["Hope is a wish; the subject changes; esperar que + subjunctive"],"answer":"Mis padres esperan que yo vaya a la universidad."}]}],[{"say":"How do science and technology shape society in the Spanish-speaking world? This theme invites debate.","blocks":[{"t":"key","text":"Topics include access to technology, social media, health care, ethics in science, and innovations from Spanish-speaking countries."},{"t":"p","text":"In persuasive essays, take a clear position and use connectors to organize ideas: en primer lugar (first), además (also), sin embargo (however), por lo tanto (therefore), en conclusión."},{"t":"p","text":"Useful vocabulary: la brecha digital (digital divide), las redes sociales (social media), el avance (advance), la investigación (research), la salud (health)."},{"t":"p","text":"For the argumentative essay, you'll read an article, examine a chart and listen to an audio source, then cite all three: Según la fuente 1…"}]},{"say":"To talk about hypothetical situations and past wishes, you need the imperfect subjunctive.","blocks":[{"t":"key","text":"Form the imperfect subjunctive from the ellos preterite: drop -ron and add -ra endings: hablaron → hablara, tuvieron → tuviera, fueron → fuera."},{"t":"p","text":"Use it after a past-tense trigger: Quería que estudiaras (I wanted you to study)."},{"t":"p","text":"Hypothetical si clauses: si + imperfect subjunctive, conditional. Si tuviera más tiempo, viajaría a Perú (If I had more time, I would travel to Peru)."},{"t":"ex","problem":"\"If technology were cheaper, more people would use it.\"","steps":["Si + imperfect subjunctive: fuera; conditional: usarían"],"answer":"Si la tecnología fuera más barata, más personas la usarían."}]}],[{"say":"The Spanish-speaking world has produced some of the world's greatest art and literature. Let's explore it.","blocks":[{"t":"key","text":"Visual arts: Diego Velázquez (Las Meninas), Francisco Goya, Pablo Picasso (Guernica, a protest against war), Frida Kahlo (self-portraits exploring identity and pain), Diego Rivera (murals)."},{"t":"p","text":"Literature: Miguel de Cervantes (Don Quijote), Gabriel García Márquez (magical realism in Cien años de soledad), Pablo Neruda and Gabriela Mistral (Nobel Prize–winning poets), Isabel Allende."},{"t":"p","text":"Music and dance: flamenco (Spain), tango (Argentina), salsa (Caribbean), mariachi (Mexico), reggaeton."},{"t":"p","text":"Magical realism blends realistic settings with magical events, a hallmark of Latin American literature."}]},{"say":"From ancient temples to modern masterpieces, architecture reveals cultural values.","blocks":[{"t":"key","text":"Notable architecture: Mayan and Aztec pyramids (Chichén Itzá, Teotihuacán), Inca stonework (Machu Picchu), the Alhambra (Moorish palace in Granada), Antoni Gaudí's Sagrada Familia in Barcelona, and colonial cathedrals throughout Latin America."},{"t":"p","text":"Cultural blending (mestizaje) appears in art and architecture combining Indigenous, African and European influences."},{"t":"p","text":"For the interpersonal speaking task, respond naturally, ask and answer questions, and use varied vocabulary and tenses."},{"t":"p","text":"Useful phrases for expressing opinions: Me parece que… (It seems to me…), A mi parecer… (In my opinion…), Estoy de acuerdo (I agree), No estoy de acuerdo (I disagree)."}]}],[{"say":"How do young people in Spanish-speaking countries live, study and work today? Let's compare.","blocks":[{"t":"key","text":"Contemporary life topics include education systems, careers, travel, holidays, leisure and relationships."},{"t":"p","text":"Formal writing (the email reply task): use a formal greeting (Estimado/a señor/a), usted forms, respond to all questions, ask for more details, and close politely (Atentamente)."},{"t":"p","text":"Useful vocabulary: la carrera (career, college major), el empleo (job), la entrevista (interview), el ocio (leisure), las vacaciones."},{"t":"ex","problem":"Begin a formal email replying to a job offer.","steps":["Formal greeting and usted"],"answer":"Estimado señor García: Le agradezco su mensaje sobre el puesto…"}]},{"say":"Identity is shaped by language, heritage, beliefs and community. This theme explores who we are.","blocks":[{"t":"key","text":"Topics: bilingualism, heritage and nationality, beliefs and values, and self-image. Many people in the US are heritage speakers who grew up speaking Spanish at home."},{"t":"p","text":"The Spanish-speaking world includes 20+ countries with diverse Indigenous, African, European and Asian roots. Indigenous languages like Quechua, Guaraní and Nahuatl are still spoken by millions."},{"t":"p","text":"For cultural comparisons, organize your presentation: introduction, description of the practice, comparison with your community, conclusion. Speak for the full two minutes."}]}],[{"say":"The final theme asks how communities face global challenges like climate change, poverty and human rights.","blocks":[{"t":"key","text":"Topics: the environment (deforestation of the Amazon, water scarcity), economic issues (poverty, migration), human rights, health and peace."},{"t":"p","text":"Vocabulary: el medio ambiente (environment), el cambio climático (climate change), la pobreza (poverty), los derechos humanos (human rights), la sostenibilidad (sustainability)."},{"t":"p","text":"Express solutions with the subjunctive: Es necesario que los gobiernos protejan los bosques. Para que (so that) always takes the subjunctive: Reciclamos para que el planeta esté limpio."},{"t":"ex","problem":"\"We must act so that future generations have clean water.\"","steps":["Para que triggers the subjunctive: tengan"],"answer":"Debemos actuar para que las futuras generaciones tengan agua limpia."}]},{"say":"Let's finish with strategies for every part of the AP Spanish exam.","blocks":[{"t":"key","text":"The exam tests interpretive (reading and listening), interpersonal (email and conversation) and presentational (essay and cultural comparison) communication."},{"t":"list","items":["Multiple choice: read the questions before the text or audio; listen for the main idea and details.","Email reply: answer every question, ask for more information, use formal register.","Argumentative essay: clear thesis, cite all three sources, use transitions.","Conversation: respond to every prompt fully, use varied tenses, keep talking for the full time.","Cultural comparison: compare a Spanish-speaking community with your own using specific examples."]},{"t":"p","text":"Use circumlocution if you forget a word: describe it instead (Es una cosa que se usa para…)."}]}]];
export default text;
